shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java')
text = path.read_text()
anchor = '    @Test\n    public void nextSourceErrorRace() {'
addition = '''    @Test
    public void innerDisposedBeforeOnSubscribe() {
        PublishSubject<Integer> ps = PublishSubject.create();
        PublishSubject<Integer> inner = PublishSubject.create();
        TestObserver<Integer> to = new TestObserver<>();

        ps.switchMap(v -> Observable.defer(() -> {
            to.dispose();
            return inner.scan(0, (a, b) -> a + b).map(w -> w * 10);
        }))
        .subscribe(to);

        ps.onNext(1);

        to.assertEmpty();
        assertTrue(to.isDisposed());
        assertFalse(ps.hasObservers());
        assertFalse(inner.hasObservers());
    }

    @Test
    public void innerDisposedBeforeOnSubscribeDelayError() {
        PublishSubject<Integer> ps = PublishSubject.create();
        PublishSubject<Integer> inner = PublishSubject.create();
        TestObserver<Integer> to = new TestObserver<>();

        ps.switchMapDelayError(v -> Observable.defer(() -> {
            to.dispose();
            return inner.scan(0, (a, b) -> a + b).map(w -> w * 10);
        }))
        .subscribe(to);

        ps.onNext(1);

        to.assertEmpty();
        assertTrue(to.isDisposed());
        assertFalse(ps.hasObservers());
        assertFalse(inner.hasObservers());
    }

'''
assert text.count(anchor) == 1
path.write_text(text.replace(anchor, addition + anchor))
PY
./gradlew --offline test --tests 'io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest.innerDisposedBeforeOnSubscribe*'

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('src/main/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchMap.java')
text = path.read_text()
old = '''            if (index == parent.unique) {
                if (t != null) {
                    queue.offer(t);
                }
                parent.drain();
            }
'''
new = '''            if (index == parent.unique) {
                SimpleQueue<R> q = queue;
                if (t != null && q != null) {
                    q.offer(t);
                }
                parent.drain();
            }
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
